import json, subprocess, sys
def run(data):
    p = subprocess.run([sys.executable,"-I","submission/main.py"], input=json.dumps(data).encode(), capture_output=True)
    return p.returncode, p.stdout.decode().strip()[:60]
def layered(width, layers, offset):
    # nodes: offset (source) ... offset+1 (pre) ... layers*width ... dest
    edges=[]
    def e(u,v): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":"x"})
    src=offset; pre=offset+1
    e(src,pre)
    first=pre+1
    for k in range(width): e(pre, first+k)
    for L in range(layers-1):
        b=first+L*width; nx=first+(L+1)*width
        for a in range(width):
            for b2 in range(width): e(b+a, nx+b2)
    last=first+(layers-1)*width
    dest=last+width
    for k in range(width): e(last+k, dest)
    return dest+1, edges
n,e = layered(2,13,0)   # dest = n-1
print("nodes",n,"paths expect 8192 ->", run({"version":1,"n":n,"capacity":[1]*n,"edges":e,"rounds":[]}))
e2 = list(e)+[{"u":0,"v":n-1,"ping_us":1,"ack_us":1,"label":"y"}]
print("8193 ->", run({"version":1,"n":n,"capacity":[1]*n,"edges":e2,"rounds":[]}))
PYEOF
